var workspace = {
    init: async function (app, container) {
        $("div[name=splitter]", container).kendoSplitter({
			scrollable: false,
			panes: [
				{ collapsible: false, size: "320px" },
				{ collapsible: false, scrollable: false }
			]
		});

        $("button[name=newConnection]", container).on("click", async function() { 
            await workspace.connect(container); 
        });

        await workspace.connect(app, container);
    },

    connect: async function(app, container) {

        var connectionInfo = new kendo.data.ObservableObject({
            environment: "",
            type: "",
            source: ""
        });

        var connectionInfoDialog = new Dialog({ title: "[resource_displayname[newconnection]]" });
        connectionInfoDialog.template = $("script[name=newConnectionDialog]").first().html();

        var environments = workspace.getEnvironments();
        var types = workspace.getTypes();
        var sources = workspace.getSources();
        var environmentApi = new Api();

        environments.change = async function() {
            environmentApi.apiRoot = this.val();
            var sources = await workspace.getSources(environmentApi);
            $("[name=source]", connectionInfoDialog.element).kendoDropDownList(sources);
        };

        connectionInfo.init(() => {
            kendo.bind(connectionInfoDialog.element, connectionInfo);
            $("[name=environment]", connectionInfoDialog.element).kendoDropDownList(environments);
            $("[name=type]", connectionInfoDialog.element).kendoDropDownList(types);
        });
    },

    getEnvironments: function(app) {
        return { dataTextField: "Name", dataValueField: "Domain", dataSource: app.Config.Deployment.Targets };
    },
    

    getTypes: function() {
        var connectionTypes = [ 
            { Name: "Content Management", Value: "ContentManagement/Page" },
            { Name: "Document Management", Value: "DocumentManagement/Folder" } 
        ];

        return { dataTextField: "Name", dataValueField: "Value", dataSource: connectionTypes };
    },

    getSources: async function(api) {
        var sources = await api.get("ContentManagement/App");
        return { dataTextField: "Name", dataValueField: "Domain", dataSource: sources.value };
    }
}
